SELECT count(*) FROM public.title title
  LEFT JOIN (SELECT key1, 1 AS hit FROM (SELECT cc.movie_id AS key1 FROM public.complete_cast cc, public.comp_cast_type cct1, public.comp_cast_type cct2 WHERE cct1.id = cc.subject_id AND cct2.id = cc.status_id AND cct1.kind = 'cast' AND cct2.kind = 'complete+verified' INTERSECT SELECT ci.movie_id AS key1 FROM public.cast_info ci, public.name n WHERE n.id = ci.person_id AND n.gender = 'm' INTERSECT SELECT mi.movie_id AS key1 FROM public.info_type it1, public.movie_info mi WHERE it1.id = mi.info_type_id AND it1.info = 'genres' AND (mi.info = 'Horror' OR mi.info = 'Action' OR mi.info = 'Sci-Fi' OR mi.info = 'Thriller' OR mi.info = 'Crime' OR mi.info = 'War') INTERSECT SELECT mi_idx.movie_id AS key1 FROM public.info_type it2, public.movie_info_idx mi_idx WHERE it2.id = mi_idx.info_type_id AND it2.info = 'votes' INTERSECT SELECT mk.movie_id AS key1 FROM public.keyword k, public.movie_keyword mk WHERE k.id = mk.keyword_id AND (k.keyword = 'murder' OR k.keyword = 'violence' OR k.keyword = 'blood' OR k.keyword = 'gore' OR k.keyword = 'death' OR k.keyword = 'female-nudity' OR k.keyword = 'hospital')) x) b1 ON title.id = b1.key1
WHERE b1.hit IS NOT NULL;
